(()=>{'use strict';
const $=id=>document.getElementById(id),KEY='aio-ultimate-onboarding-v1';
let step=0,font='inter',wall='default',cursor='chatgpt',fontChosen=false,wallChosen=false,cursorChosen=false,frozen=false,session=null,priceCache=new Map(),menuIndex=0;
const rpc=async(n,a)=>{if(typeof supabaseClient==='undefined'||!supabaseClient)throw Error('Supabase is not ready.');const r=await supabaseClient.rpc(n,a||{});if(r.error)throw r.error;return r.data};
const ECONOMY_CACHE_KEY='aio-economy-offline-cache-v1',OFFLINE_PURCHASE_QUEUE_KEY='aio-offline-game-purchases-v1';
function startAioLiveClock(){const el=$('aioLiveClock');if(!el||el.dataset.clockBound==='1')return;el.dataset.clockBound='1';let timer=0;const tick=()=>{el.textContent=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false});if(timer)clearTimeout(timer);if(!document.hidden)timer=setTimeout(tick,60000-(Date.now()%60000)+40)};tick();document.addEventListener('visibilitychange',()=>{if(timer)clearTimeout(timer);timer=0;if(!document.hidden)tick()})}
function readLocalJSON(key,fallback){try{const value=localStorage.getItem(key);return value===null?fallback:JSON.parse(value)}catch{return fallback}}
function writeLocalJSON(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function readOfflineEconomyCache(){const cache=readLocalJSON(ECONOMY_CACHE_KEY,null);return cache&&typeof cache==='object'?cache:null}
function readOfflinePurchaseQueue(){const queue=readLocalJSON(OFFLINE_PURCHASE_QUEUE_KEY,[]);return Array.isArray(queue)?queue.filter(x=>x&&typeof x.gameId==='string'&&typeof x.userId==='string'):[]}
function saveOfflineEconomyCache(state,prices,owned){if(!signed())return;writeLocalJSON(ECONOMY_CACHE_KEY,{userId:currentUser.id,balance:Number(state.balance)||0,quests:Array.isArray(state.quests)?state.quests:[],prices:(prices||[]).map(x=>({game_id:x.game_id,price:Number(x.price)||0})),owned:[...(owned||[])],syncedAt:Date.now()})}
function renderOfflineQueuePanel(root){if(!root)return;let panel=root.querySelector('#aioOfflineQueue');if(!panel){panel=document.createElement('section');panel.id='aioOfflineQueue';panel.className='aio-offline-queue';const owner=root.querySelector('#aioOwnerEconomy');if(owner)root.insertBefore(panel,owner);else root.append(panel)}const queue=readOfflinePurchaseQueue().filter(x=>signed()&&x.userId===currentUser.id);const reserved=queue.reduce((sum,x)=>sum+(Number(x.price)||0),0);panel.innerHTML='<div class="aio-offline-queue-head"><div><strong>Offline purchase queue</strong><small>'+(navigator.onLine?'Connected · queued purchases will be checked with the server.':'Offline · queued purchases wait until you reconnect.')+'</small></div><span>'+queue.length+' queued · '+reserved.toLocaleString()+' ◈ reserved</span></div>'+(queue.length?'<div class="aio-offline-queue-list">'+queue.map(x=>'<div class="aio-offline-queue-row"><span>'+esc(gameName(x.gameId))+'</span><strong>'+Number(x.price).toLocaleString()+' ◈</strong><small>'+(x.priceChanged?'Price changed · review':'Waiting to sync')+'</small><button type="button" data-remove-queued="'+esc(x.id)+'" aria-label="Remove queued purchase">Remove</button></div>').join('')+'</div>':'<p class="aio-onboard-note">No pending purchases. You can queue a game purchase while offline using your last synced balance and prices.</p>');panel.querySelectorAll('[data-remove-queued]').forEach(b=>b.onclick=()=>{const updated=readOfflinePurchaseQueue().filter(x=>x.id!==b.dataset.removeQueued);writeLocalJSON(OFFLINE_PURCHASE_QUEUE_KEY,updated);renderOfflineQueuePanel(root)})}
function queueOfflineGame(id){if(!signed())throw Error('Sign in before queuing a purchase.');const cache=readOfflineEconomyCache();if(!cache||cache.userId!==currentUser.id)throw Error('Connect once to sync your A-Coins balance before using offline purchases.');if(Date.now()-Number(cache.syncedAt||0)>7*24*60*60*1000)throw Error('Your saved balance is over 7 days old. Connect to refresh it first.');const priceRow=(cache.prices||[]).find(x=>x.game_id===id);if(!priceRow)throw Error('This game price is not in your offline catalogue. Connect to refresh the shop.');const price=Number(priceRow.price)||0;if(price<=0)throw Error('This game is free or has no offline purchase price.');if((cache.owned||[]).includes(id))throw Error('You already own this game.');const queue=readOfflinePurchaseQueue();if(queue.some(x=>x.userId===currentUser.id&&x.gameId===id))throw Error('This game is already in your offline queue.');const reserved=queue.filter(x=>x.userId===currentUser.id).reduce((sum,x)=>sum+(Number(x.price)||0),0);if(Number(cache.balance)-reserved<price)throw Error('Your last synced balance is not enough for this queued purchase.');const entry={id:(crypto.randomUUID?.()||('q-'+Date.now()+'-'+Math.random().toString(36).slice(2))),userId:currentUser.id,gameId:id,price,queuedAt:Date.now(),priceChanged:false};queue.push(entry);if(!writeLocalJSON(OFFLINE_PURCHASE_QUEUE_KEY,queue))throw Error('This browser could not save the offline queue.');toast('Purchase queued. It will be checked and completed when you reconnect.');renderOfflineQueuePanel($('aioEconomyContent'));return entry}
function renderCachedOfflineEconomy(root,cache){const prices=Array.isArray(cache.prices)?cache.prices:[],owned=new Set(cache.owned||[]),queue=readOfflinePurchaseQueue().filter(x=>x.userId===cache.userId),reserved=queue.reduce((sum,x)=>sum+(Number(x.price)||0),0),available=Math.max(0,Number(cache.balance||0)-reserved);priceCache=new Map(prices.map(x=>[x.game_id,Number(x.price)||0]));root.innerHTML='<div class="aio-wallet-card"><div><span>LAST SYNCED BALANCE</span><strong>◈ '+available.toLocaleString()+' A-Coins</strong></div><small>Offline view · '+reserved.toLocaleString()+' ◈ reserved in queued purchases. Final balances are checked by the server when you reconnect.</small></div><div class="aio-offline-notice">You are offline. Quest claims and purchases are not final until All in One Edition reconnects and confirms them.</div><div class="aio-quest-heading"><h3>Saved quests</h3><span>Read-only while offline</span></div><div class="aio-quest-grid">'+(cache.quests||[]).map(q=>'<article class="aio-quest-card"><div class="aio-quest-top"><span>'+esc(q.period)+'</span><b>+'+Number(q.reward)+' ◈</b></div><h4>'+esc(q.title)+'</h4><p>'+esc(q.description)+'</p><div class="aio-quest-progress"><span style="width:'+Math.min(100,Math.round(Number(q.progress||0)/Math.max(1,Number(q.target||1))*100))+'%"></span></div><div class="aio-quest-foot"><span>'+Number(q.progress||0)+' / '+Number(q.target||0)+'</span><span>'+(q.claimed?'Claimed':'Connect to claim')+'</span></div></article>').join('')+'</div><div class="aio-pricing-section"><h3>Saved game shop</h3><div class="aio-pricing-list">'+prices.filter(x=>Number(x.price)>0).map(p=>'<div class="aio-pricing-row"><span>'+esc(gameName(p.game_id))+'</span><strong>'+Number(p.price).toLocaleString()+' ◈</strong>'+(owned.has(p.game_id)?'<span class="aio-owned">Owned</span>':queue.some(q=>q.gameId===p.game_id)?'<span>Queued</span>':'<button class="aio-small-primary" data-buy="'+esc(p.game_id)+'">Queue purchase</button>')+'</div>').join('')+'</div></div>';root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{try{queueOfflineGame(b.dataset.buy);renderCachedOfflineEconomy(root,readOfflineEconomyCache()||cache)}catch(e){toast(e.message||'Could not queue purchase.')}});renderOfflineQueuePanel(root)}
let offlineSyncBusy=false;
async function syncOfflineGamePurchases(){
 if(offlineSyncBusy||!navigator.onLine||!signed()||typeof supabaseClient==='undefined'||!supabaseClient)return;
 const queue=readOfflinePurchaseQueue(),mine=queue.filter(x=>x.userId===currentUser.id&&!x.priceChanged);
 if(!mine.length)return;
 offlineSyncBusy=true;let completed=0,changed=0,failedFunds=0;
 const keep=queue.filter(x=>x.userId!==currentUser.id||x.priceChanged);
 for(let index=0;index<mine.length;index++){
  const item=mine[index];
  try{
   const priceResult=await supabaseClient.from('aio_game_prices').select('price').eq('game_id',item.gameId).maybeSingle();
   if(priceResult.error)throw priceResult.error;
   if(!priceResult.data||Number(priceResult.data.price)!==Number(item.price)){
    keep.push({...item,priceChanged:true});changed++;continue;
   }
   const result=await rpc('aio_buy_game',{p_game_id:item.gameId});
   if(result?.ok){completed++;continue;}
   keep.push(item);
  }catch(error){
   const message=String(error?.message||'');
   if(/not enough A-Coins|already owned/i.test(message)){failedFunds++;continue;}
   keep.push(item,...mine.slice(index+1));break;
  }
 }
 writeLocalJSON(OFFLINE_PURCHASE_QUEUE_KEY,keep);
 offlineSyncBusy=false;
 if(completed)toast(completed+' queued purchase'+(completed===1?'':'s')+' confirmed by the server.');
 if(changed)toast(changed+' queued price'+(changed===1?' has':'s have')+' changed. Remove it and buy again at the current price.');
 if(failedFunds)toast(failedFunds+' queued purchase'+(failedFunds===1?' was':'s were')+' not completed because the balance or ownership check failed.');
 if(completed||changed||failedFunds||$('aioCoinModal')?.classList.contains('open'))await renderEconomy();else renderBalance();
}
const toast=s=>typeof showToast==='function'?showToast(s):console.info(s);
const slug=s=>String(s||'game').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,110)||'game';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const appearance=()=>window.AIOAppearance?.getState?.()||{};
const setChoice=o=>window.AIOAppearance?.setChoice?.(o);
const signed=()=>{try{return typeof currentUser!=='undefined'&&!!currentUser}catch{return false}};
const walls=()=>window.AIOAppearance?.getWallpapers?.()||[{id:'default',name:'Default',bg:'linear-gradient(135deg,#f7f7f8,#e8edf7)'},{id:'midnight',name:'Midnight',bg:'linear-gradient(135deg,#05070f,#28334d)'},{id:'aurora',name:'Aurora',bg:'linear-gradient(135deg,#10152d,#42e8c5)'},{id:'arcade',name:'Arcade neon',bg:'linear-gradient(135deg,#11112b,#ff4dd2)'}];
function ensureOnboard(){if($('aioOnboarding'))return;const m=document.createElement('div');m.id='aioOnboarding';m.className='aio-ultimate-modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');m.innerHTML='<div class="aio-onboard-card"><div class="aio-onboard-top"><div class="aio-onboard-mark">A</div><span id="aioOnboardStep">PERSONALISE YOUR HUB</span><button class="aio-icon-button" id="aioOnboardClose" aria-label="Close tutorial">×</button></div><div id="aioOnboardContent"></div><div class="aio-onboard-footer"><span>Your choices save automatically.</span><div id="aioOnboardActions"></div></div></div>';document.body.append(m);$('aioOnboardClose').onclick=()=>{if(step===0&&!fontChosen){toast('Choose a font before continuing.');return}closeOnboard()}}
function openOnboard(reset){ensureOnboard();if(reset)localStorage.removeItem(KEY);const a=appearance();font=a.font||'inter';wall=a.wallpaper||'default';cursor=a.cursorStyle||'chatgpt';fontChosen=false;wallChosen=false;cursorChosen=false;step=0;renderOnboard();$('aioOnboarding').classList.add('open');document.body.classList.add('aio-onboarding-open')}
function closeOnboard(){ $('aioOnboarding')?.classList.remove('open');document.body.classList.remove('aio-onboarding-open')}
function renderOnboard(){const c=$('aioOnboardContent'),a=$('aioOnboardActions'),set=(n,title,copy)=>{$('aioOnboardStep').textContent=n;c.innerHTML='<h2>'+title+'</h2><p class="aio-onboard-copy">'+copy+'</p>'};
if(step===0){set('STEP 1 OF 4 · TYPE','Choose your font','Pick a typeface for the whole hub. Each preview uses the font being demonstrated.');c.innerHTML+='<div class="aio-font-choices">'+[['system','Default / System','system-ui,sans-serif'],['inter','Inter','Inter,system-ui,sans-serif'],['nunito','Nunito','Nunito,system-ui,sans-serif'],['cherry','Cherry Bomb One','"Cherry Bomb One",system-ui,sans-serif']].map(x=>'<button class="aio-font-choice '+(font===x[0]?'selected':'')+'" data-font="'+x[0]+'" style="font-family:'+x[2]+'"><span>'+x[1]+'</span><strong>All in One Edition</strong><small>The quick brown fox jumps over the lazy dog.</small></button>').join('')+'</div>';c.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>{font=b.dataset.font;fontChosen=true;setChoice({font});renderOnboard()});a.innerHTML='<button class="aio-primary-button" id="aioNext" '+(fontChosen?'':'disabled')+'>Continue →</button>';a.querySelector('button').onclick=()=>{if(!fontChosen){toast('Choose a font to continue.');return}step=1;renderOnboard()}}
else if(step===1){set('STEP 2 OF 4 · BACKGROUND','Choose your wallpaper','Select a background. The real site wallpaper updates immediately.');c.innerHTML+='<div class="aio-wallpaper-choices">'+walls().map(w=>'<button class="aio-wall-choice '+(wall===w.id?'selected':'')+'" data-wall="'+esc(w.id)+'"><span class="aio-wall-preview" style="background:'+w.bg+'"></span><span>'+esc(w.name)+'</span>'+(wall===w.id?'<b>✓</b>':'')+'</button>').join('')+'</div><p class="aio-onboard-note">Custom uploads remain in Settings when supported.</p>';c.querySelectorAll('[data-wall]').forEach(b=>b.onclick=()=>{wall=b.dataset.wall;wallChosen=true;setChoice({wallpaper:wall});renderOnboard()});a.innerHTML='<button class="aio-secondary-button" id="aioBack">Back</button><button class="aio-primary-button" id="aioNext" '+(wallChosen?'':'disabled')+'>Choose →</button>';a.querySelector('#aioBack').onclick=()=>{step=0;renderOnboard()};a.querySelector('#aioNext').onclick=()=>{step=2;renderOnboard()}}
else if(step===2){set('STEP 3 OF 4 · POINTER','Choose your cursor','Lightweight pointer styles. Text fields keep normal text-selection behaviour.');c.innerHTML+='<div class="aio-cursor-choices">'+[['default','Default','Use browser cursor.'],['minimal','Minimal','Clean native states.'],['chatgpt','ChatGPT-inspired','A small, sharp custom pointer.']].map(x=>'<button class="aio-cursor-choice '+(cursor===x[0]?'selected':'')+'" data-cursor="'+x[0]+'"><span class="aio-cursor-preview '+x[0]+'">↖</span><strong>'+x[1]+'</strong><small>'+x[2]+'</small></button>').join('')+'</div>';c.querySelectorAll('[data-cursor]').forEach(b=>b.onclick=()=>{cursor=b.dataset.cursor;cursorChosen=true;setChoice({cursorStyle:cursor});renderOnboard()});a.innerHTML='<button class="aio-secondary-button" id="aioBack">Back</button><button class="aio-primary-button" id="aioNext" '+(cursorChosen?'':'disabled')+'>Choose →</button>';a.querySelector('#aioBack').onclick=()=>{step=1;renderOnboard()};a.querySelector('#aioNext').onclick=()=>{if(!cursorChosen){toast('Choose a cursor first.');return}step=3;renderOnboard()}}
else{set('STEP 4 OF 4 · READY','You’re ready.','Your hub is personalised. You can reopen this setup from Settings → Personalisation.');c.innerHTML+='<div class="aio-summary-list"><div><span>Font</span><strong>'+esc(({system:'Default / System',inter:'Inter',nunito:'Nunito',cherry:'Cherry Bomb One',sakura:'Sakura (fallback)'})[font])+'</strong></div><div><span>Wallpaper</span><strong>'+esc(walls().find(w=>w.id===wall)?.name||wall)+'</strong></div><div><span>Cursor</span><strong>'+esc(({default:'Default',minimal:'Minimal',chatgpt:'ChatGPT-inspired'})[cursor])+'</strong></div></div>';a.innerHTML='<button class="aio-primary-button" id="aioEnter">Enter All in One Edition →</button>';a.querySelector('button').onclick=()=>{localStorage.setItem(KEY,JSON.stringify({completed:true,font,wallpaper:wall,cursor,at:Date.now()}));closeOnboard();toast('Personalisation saved. Enjoy the hub!')}}
}
function addTutorialSetting(){const root=$('aioAppearanceRoot');if(!root||root.querySelector('#aioSetupTutorial'))return;const s=document.createElement('section');s.className='aio-appearance-section';s.id='aioSetupTutorial';s.innerHTML='<div class="aio-appearance-section-head"><strong>Personalisation tutorial</strong><span>Reopen the first-time setup or reset it for the next visit.</span></div><div class="aio-setup-actions"><button class="btn mini primary" id="aioRunTutorial">Setup Tutorial</button><button class="btn mini" id="aioResetTutorial">Reset Tutorial</button></div>';root.append(s);$('aioRunTutorial').onclick=()=>openOnboard(true);$('aioResetTutorial').onclick=()=>{localStorage.removeItem(KEY);toast('Tutorial reset. It will appear next visit.')}}

let discoveryFilter='all',pricesLoaded=false;
function loadPrices(){try{if(typeof supabaseClient==='undefined'||!supabaseClient)return;supabaseClient.from('aio_game_prices').select('game_id,price').then(r=>{if(r.error)throw r.error;priceCache=new Map((r.data||[]).map(x=>[x.game_id,Number(x.price)]));pricesLoaded=true;addSourceLabels();if(discoveryFilter==='free'&&typeof renderGames==='function')renderGames()}).catch(e=>console.info('Price cache unavailable:',e.message))}catch{}}
function addDiscoveryToolbar(){const grid=$('gameGrid');if(!grid||$('aioDiscoveryFilters'))return;const bar=document.createElement('div');bar.id='aioDiscoveryFilters';bar.className='aio-discovery-filters';bar.innerHTML='<button data-discovery="all" class="active">All games</button><button data-discovery="recent">Recently played</button><button data-discovery="favourites">Favourites</button><button data-discovery="new">New</button><button data-discovery="free">Free games</button><button data-discovery="random">Random game</button>';grid.parentElement.insertBefore(bar,grid);bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{const f=b.dataset.discovery;if(f==='random'){const games=typeof GAMES!=='undefined'?GAMES.filter(g=>priceCache.get(slug(g.id||g.name))===0||!priceCache.has(slug(g.id||g.name))):[];if(games.length&&typeof window.openGame==='function')window.openGame(GAMES.indexOf(games[Math.floor(Math.random()*games.length)]));else toast('The catalogue is still loading. Try again shortly.');return}discoveryFilter=f;bar.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));if(f==='free'&&!pricesLoaded)loadPrices();if(typeof renderGames==='function')renderGames()})}
function patchDiscoveryFilter(){if(typeof window.filteredGames!=='function'||window.filteredGames.__aioDiscovery)return;const orig=window.filteredGames;const f=function(){let list=orig();if(discoveryFilter==='favourites'){const fav=favourites();list=list.filter(x=>typeof favouriteGames!=='undefined'&&favouriteGames.has(gameKey(x.g)))}else if(discoveryFilter==='recent'){list=list.filter(x=>Number((gameProgress[gameKey(x.g)]||{}).lastPlayed||0)>0).sort((a,b)=>Number((gameProgress[gameKey(b.g)]||{}).lastPlayed||0)-Number((gameProgress[gameKey(a.g)]||{}).lastPlayed||0))}else if(discoveryFilter==='new'){list=list.filter(x=>x.g.new||/new/i.test(x.g.tag||''))}else if(discoveryFilter==='free'){if(!pricesLoaded)return [];list=list.filter(x=>(priceCache.get(slug(x.g.id||x.g.name))||0)===0)}return list};f.__aioDiscovery=true;window.filteredGames=f}
function enhanceSmartAI(){if(typeof window.executeSmartCommand!=='function'||window.executeSmartCommand.__aioCatalog)return;const orig=window.executeSmartCommand;const f=function(raw){const q=String(raw||'').toLowerCase();if(/a-coins?|earn coins?|coin balance|quest rewards?/.test(q))return 'A-Coins are earned through qualifying game sessions: 10 A-Coins after at least 90 seconds, up to 5 session rewards per UTC day. Quests: Warm up (+25 daily for one session), Triple play (+75 daily for three sessions), Try something new (+100 daily for three different games), and Weekly player (+200 for ten sessions in a UTC week). Open A-Coins & Quests to see live progress and claim rewards.';if(/free.*racing|racing.*free/.test(q)){const games=typeof GAMES!=='undefined'?GAMES.filter(g=>/racing|race|kart/i.test((g.name||'')+' '+(g.cat||'')+' '+(g.description||''))&&(pricesLoaded?(priceCache.get(slug(g.id||g.name))||0)===0:!g.coinPrice)):[];if(!games.length)return 'I could not verify a free racing game in the loaded catalogue. Search “racing” in Games; I will not invent a title or price.';return 'Free racing games in the current catalogue: '+games.slice(0,5).map(g=>g.name).join(', ')+'.'}if(/what game should i play|recommend.*game|random game/.test(q)){const games=typeof GAMES!=='undefined'?GAMES.filter(g=>String(g.source||'').includes('mashukui/web-games')&&(pricesLoaded?(priceCache.get(slug(g.id||g.name))||0)===0:true)):[];if(!games.length)return 'Use Random game or the category filters to choose from the live catalogue.';const g=games[Math.floor(Math.random()*games.length)];return 'Try '+g.name+' ('+g.cat+'). '+(g.description||'See the game page for instructions.')}return orig(raw)};f.__aioCatalog=true;window.executeSmartCommand=f}

function addSlime(){try{if(typeof GAMES==='undefined'||GAMES.some(g=>/pizzaedition\.com\/g\/slimekeyboardescape/i.test(g.url||'')))return;GAMES.push({id:'slime-keyboard-escape',name:'Slime Keyboard Escape',description:'A solo platform-running game set on a giant keyboard. Build speed, jump gaps, reach checkpoints and bank wins.',cat:'Platformer',url:'https://pizzaedition.com/g/slimekeyboardescape',source:'Pizza Edition',sourceUrl:'https://pizzaedition.com/g/slimekeyboardescape',img:'',tag:'New',controls:'WASD or arrow keys to move; mouse to change camera; Space to jump; C for skins; R for rebirth; P for shop; T for treadmill; E to interact. Touch screens use an on-screen joystick and jump button.',license:'Externally hosted by Pizza Edition; not redistributed',new:true,coinPrice:0,coinReward:10,questEligible:true,difficulty:'Normal',fullscreenSupported:true,multiplayer:false});if(typeof renderFilters==='function')renderFilters();if(typeof renderGames==='function')renderGames()}catch(e){console.warn(e)}}
function addOpenSourceGames(){try{if(typeof GAMES==='undefined')return;const data=[['ant-flap','Ant Flap','Arcade'],['ant-jump','Ant Jump','Arcade'],['block-drop','Block Drop','Arcade'],['breakout','Breakout','Arcade'],['paddle-duel','Paddle Duel','Arcade'],['stack-tower','Stack Tower','Arcade'],['whack-a-mole','Whack-a-Mole','Arcade'],['snake','Snake','Classic'],['tic-tac-toe','Tic Tac Toe','Classic'],['connect-four','Connect Four','Classic'],['2048','2048','Puzzle'],['minesweeper','Minesweeper','Puzzle'],['memory-match','Memory Match','Puzzle'],['dino-run','Dino Run','Action'],['piano-tap','Piano Tap','Arcade'],['cross-road','Cross Road','Arcade'],['slide-puzzle','Slide Puzzle','Puzzle'],['bubble-shooter','Bubble Shooter','Arcade'],['sudoku','Sudoku','Puzzle'],['merge-drop','Merge Drop','Puzzle'],['water-sort','Water Sort','Puzzle'],['helix-drop','Helix Drop','Action'],['gem-match','Gem Match','Puzzle'],['maze-muncher','Maze Muncher','Arcade'],['air-hockey','Air Hockey','Action'],['reversi','Reversi','Classic'],['sokoban','Sokoban','Puzzle'],['lights-out','Lights Out','Puzzle'],['hanoi','Hanoi','Puzzle'],['pipe-connect','Pipe Connect','Puzzle'],['rush-hour','Rush Hour','Puzzle'],['mahjong-link','Mahjong Link','Puzzle'],['nonogram','Nonogram','Puzzle'],['checkers','Checkers','Classic'],['snakes-ladders','Snakes and Ladders','Classic'],['hoop-shot','Hoop Shot','Action'],['mini-golf','Mini Golf','Action'],['helicopter','Helicopter','Arcade'],['balloon-pop','Balloon Pop','Arcade'],['simon-says','Simon Says','Arcade'],['gomoku','Gomoku','Classic'],['mancala','Mancala','Classic'],['bowling','Bowling','Action'],['penalty-kick','Penalty Kick','Action']];let added=0;for(const [id,name,cat] of data){const url='https://mashukui.github.io/web-games/'+id+'/';if(GAMES.some(g=>slug(g.id||g.name)===id||g.url===url))continue;GAMES.push({id,name,description:name+' browser game from the MIT-licensed mashukui/web-games collection.',cat,url,source:'Open-source: mashukui/web-games',sourceUrl:'https://github.com/mashukui/web-games',img:'',tag:'MIT',controls:'Use the instructions shown in the game. The collection supports keyboard, mouse and touch where appropriate.',license:'MIT © 2026 mashukui; see the source repository for licence text.',featured:false,new:true,coinPrice:0,coinReward:10,questEligible:true,difficulty:'Normal',fullscreenSupported:true,multiplayer:id==='tic-tac-toe'});added++}window.AIOGameRegistry={list:()=>GAMES.map(g=>({id:slug(g.id||g.name),title:g.name,description:g.description||'',category:g.cat||'Other',thumbnail:g.img||'',source:g.source||'Existing catalogue',sourceUrl:g.sourceUrl||g.url||'',launchUrl:g.url||'',controls:g.controls||'See game instructions.',tags:g.tags||[],featured:!!g.featured,new:!!g.new,coinPrice:Number(g.coinPrice||0),coinReward:Number(g.coinReward||0),questEligible:g.questEligible!==false,difficulty:g.difficulty||'Normal',fullscreenSupported:g.fullscreenSupported!==false,multiplayer:!!g.multiplayer,license:g.license||'Not verified'})),find:id=>GAMES.find(g=>slug(g.id||g.name)===id||g.name===id)||null};if(added&&typeof renderFilters==='function')renderFilters();if(added&&typeof renderGames==='function')renderGames()}catch(e){console.warn('Open-source catalogue import:',e)}}
function addSourceLabels(){document.querySelectorAll('#gameGrid .aio-source-label').forEach(el=>el.remove());document.querySelectorAll('#gameGrid .card').forEach(card=>{const meta=card.querySelector('.card-meta');if(!meta)return;const name=card.querySelector('.card-title')?.textContent||'';let g=null;try{g=GAMES.find(x=>x.name===name)}catch{}const id=slug(g?.id||name),price=priceCache.get(id);if(Number(price)>0&&!card.querySelector('.aio-price-label')){const p=document.createElement('span');p.className='aio-price-label';p.textContent='Play for '+Number(price).toLocaleString()+' A-Coins';meta.append(p)}if(Number(price)<=0)meta.querySelector('.aio-price-label')?.remove()})}
function setupGameControls(){const stage=$('gameStage');if(!stage||$('aioGameToolbar'))return;const bar=document.createElement('div');bar.id='aioGameToolbar';bar.className='aio-game-toolbar';bar.innerHTML='<button id="aioFreezeBtn">Freeze</button><button id="aioGameFullBtn">Fullscreen</button><button id="aioGameRestartBtn">Restart</button><button id="aioGameInfoBtn">Info</button><button id="aioGameExitBtn">Exit</button>';stage.append(bar);const o=document.createElement('div');o.id='aioFrozenOverlay';o.className='aio-frozen-overlay';o.innerHTML='<div class="aio-frozen-card"><div class="aio-frozen-icon">Ⅱ</div><h3>Game input blocked</h3><p>This game may not support true pausing. Input is temporarily blocked; an external game may continue running.</p><button class="aio-primary-button" id="aioResumeBtn">Resume</button></div>';stage.append(o);$('aioFreezeBtn').onclick=()=>freeze(!frozen);$('aioResumeBtn').onclick=()=>freeze(false);$('aioGameFullBtn').onclick=()=>window.fullscreenGame?.();$('aioGameRestartBtn').onclick=()=>window.reloadGame?.();$('aioGameInfoBtn').onclick=gameInfo;$('aioGameExitBtn').onclick=()=>window.closeGame?.()}
function freeze(v){frozen=!!v;const f=$('gameFrame');if(f){f.style.pointerEvents=frozen?'none':'';if(frozen){try{f.contentWindow.postMessage({type:'pause'},'*')}catch{}try{f.blur()}catch{}}}const overlay=$('aioFrozenOverlay');overlay?.classList.toggle('open',frozen);if($('aioFreezeBtn'))$('aioFreezeBtn').textContent=frozen?'Resume':'Freeze';if(frozen){setTimeout(()=>$('aioResumeBtn')?.focus(),0)}else if($('gameModal')?.classList.contains('open')){setTimeout(()=>{try{$('gameFrame')?.focus({preventScroll:true})}catch{}},0)}}
function gameInfo(){let g=null;try{g=GAMES.find(x=>x.name===$('modalTitle')?.textContent)}catch{}alert((g?.name||$('modalTitle')?.textContent||'Game')+'\nCategory: '+(g?.cat||'Unknown')+'\nURL: '+(g?.url||'Not available')+'\nControls: '+(g?.controls||'Check the original game instructions.')+'\nLicence: '+(g?.license||'Source licence not verified.'))}
function gameName(id){try{return GAMES.find(g=>slug(g.id||g.name)===id||slug(g.name)===id)?.name||id}catch{return id}}
async function beginSession(g){if(!signed()||g?.questEligible===false||Number(g?.coinReward||0)<=0)return;try{session=await rpc('aio_start_game_session',{p_game_id:slug(g.id||g.name)});localStorage.setItem('aio-active-game-session-v1',JSON.stringify({id:session,started:Date.now()}))}catch(e){console.info('Session reward unavailable:',e.message)}}
async function endSession(){const id=session;session=null;localStorage.removeItem('aio-active-game-session-v1');if(!id||!signed())return;try{const r=await rpc('aio_finish_game_session',{p_session_id:id});if(r.reward>0)toast('+'+r.reward+' A-Coins earned!');if($('aioCoinModal')?.classList.contains('open'))renderEconomy()}catch(e){if(!/90 seconds/i.test(e.message||''))console.info(e.message)}}
async function priceFor(id){if(priceCache.has(id))return priceCache.get(id);try{const {data,error}=await supabaseClient.from('aio_game_prices').select('price').eq('game_id',id).maybeSingle();if(error)throw error;const p=Number(data?.price||0);priceCache.set(id,p);return p}catch(e){toast('Could not verify this game price. Retry in a moment.');return null}}
async function canLaunch(g){const id=slug(g.id||g.name),price=await priceFor(id);if(price===null)return false;if(!price)return true;if(!signed()){toast('Sign in to purchase this game with A-Coins.');window.handleAccountClick?.();return false}try{const {data,error}=await supabaseClient.from('aio_game_purchases').select('id,refunded_at').eq('user_id',currentUser.id).eq('game_id',id).is('refunded_at',null).maybeSingle();if(error)throw error;if(data&&!data.refunded_at)return true;if(!confirm('Play '+g.name+' for '+price.toLocaleString()+' A-Coins?'))return false;await rpc('aio_buy_game',{p_game_id:id});priceCache.delete(id);toast('Game purchased.');return true}catch(e){toast(e.message||'Could not purchase this game.');return false}}
function patchGameLaunch(){if(typeof window.openCurrentGameNewTab==='function'&&!window.openCurrentGameNewTab.__aioPriceGate){const guardedOpen=function(){let g=null;try{g=typeof currentGame!=='undefined'?currentGame:null}catch{}if(!g)return null;const popup=window.open('about:blank','_blank');if(!popup){toast('Allow pop-ups to open a game in a new tab.');return null}try{popup.opener=null}catch{};Promise.resolve(canLaunch(g)).then(ok=>{if(!ok){popup.close();return}try{popup.location.replace(g.url)}catch(e){popup.close();toast('Could not open this game in a new tab.')}}).catch(e=>{popup.close();toast('Could not verify this game: '+(e?.message||'try again'))});return popup};guardedOpen.__aioPriceGate=true;window.openCurrentGameNewTab=guardedOpen}if(typeof window.openGame==='function'&&!window.openGame.__aioPatched){const orig=window.openGame;const f=async i=>{const g=typeof GAMES!=='undefined'?GAMES[i]:null;if(!g||!await canLaunch(g))return;const frame=$('gameFrame');if(frame&&g.source==='Community')frame.setAttribute('sandbox','allow-scripts allow-forms allow-pointer-lock allow-popups');else frame?.removeAttribute('sandbox');await endSession();orig(i);setupGameControls();freeze(false);beginSession(g)};f.__aioPatched=true;window.openGame=f}if(typeof window.closeGame==='function'&&!window.closeGame.__aioPatched){const orig=window.closeGame;const f=function(){freeze(false);endSession();$('gameFrame')?.removeAttribute('sandbox');return orig.apply(this,arguments)};f.__aioPatched=true;window.closeGame=f}}
function ensureCoinUI(){if(!$('aioCoinButton')){const top=document.querySelector('.top'),b=document.createElement('button');if(top){b.id='aioCoinButton';b.className='btn aio-coin-button';b.innerHTML='◈ <span id="aioCoinBalance">A-Coins</span>';b.onclick=openEconomy;top.insertBefore(b,$('settingsBtn'))}}if(!$('aioCoinModal')){const m=document.createElement('div');m.id='aioCoinModal';m.className='aio-ultimate-modal aio-economy-modal';m.innerHTML='<div class="aio-economy-card"><div class="aio-economy-head"><div><span class="aio-kicker">YOUR PROGRESSION</span><h2>A-Coins & Quests</h2></div><button class="aio-icon-button" id="aioCoinClose">×</button></div><div id="aioEconomyContent">Loading…</div></div>';document.body.append(m);$('aioCoinClose').onclick=()=>m.classList.remove('open')}}
async function openEconomy(){ensureCoinUI();$('aioCoinModal').classList.add('open');await renderEconomy()}
async function renderEconomy(){const root=$('aioEconomyContent');if(!root)return;if(!signed()){root.innerHTML='<div class="aio-economy-empty"><h3>Sign in to save progress</h3><p>A-Coins and quests are linked to your account.</p><button class="aio-primary-button" id="aioCoinSignIn">Open account</button></div>';$('aioCoinSignIn').onclick=()=>{ $('aioCoinModal').classList.remove('open');window.handleAccountClick?.()};return}if(!navigator.onLine){const cache=readOfflineEconomyCache();if(cache?.userId===currentUser.id){renderCachedOfflineEconomy(root,cache);return}}root.textContent='Loading balance and quests…';try{const [state,pr,pu]=await Promise.all([rpc('aio_get_economy_state'),supabaseClient.from('aio_game_prices').select('game_id,price').order('game_id'),supabaseClient.from('aio_game_purchases').select('id,game_id,price_paid,refunded_at').eq('user_id',currentUser.id)]);if(pr.error)throw pr.error;if(pu.error)throw pu.error;priceCache=new Map((pr.data||[]).map(x=>[x.game_id,Number(x.price)]));addSourceLabels();const owned=new Set((pu.data||[]).filter(x=>!x.refunded_at).map(x=>x.game_id));saveOfflineEconomyCache(state,pr.data||[],owned);root.innerHTML='<div class="aio-wallet-card"><div><span>AVAILABLE BALANCE</span><strong>◈ '+Number(state.balance||0).toLocaleString()+' A-Coins</strong></div><small>Earned through gameplay and quests. Never sold for real money.</small></div><div class="aio-quest-heading"><h3>Quests</h3><span>Rewards claim once per period.</span></div><div class="aio-quest-grid">'+(state.quests||[]).map(q=>'<article class="aio-quest-card"><div class="aio-quest-top"><span>'+esc(q.period)+'</span><b>+'+Number(q.reward)+' ◈</b></div><h4>'+esc(q.title)+'</h4><p>'+esc(q.description)+'</p><div class="aio-quest-progress"><span style="width:'+Math.min(100,Math.round(Number(q.progress||0)/Math.max(1,Number(q.target||1))*100))+'%"></span></div><div class="aio-quest-foot"><span>'+Number(q.progress||0)+' / '+Number(q.target||0)+'</span>'+(q.claimed?'<span class="aio-claimed">Claimed ✓</span>':Number(q.progress)>=Number(q.target)?'<button class="aio-small-primary" data-claim="'+esc(q.id)+'">Claim reward</button>':'<span>In progress</span>')+'</div></article>').join('')+'</div><div class="aio-pricing-section"><h3>Priced games</h3><div class="aio-pricing-list">'+(pr.data||[]).filter(x=>Number(x.price)>0).map(p=>'<div class="aio-pricing-row"><span>'+esc(gameName(p.game_id))+'</span><strong>'+Number(p.price).toLocaleString()+' ◈</strong>'+(owned.has(p.game_id)?'<span class="aio-owned">Owned</span>':'<button class="aio-small-primary" data-buy="'+esc(p.game_id)+'">Buy</button>')+'</div>').join('')+'</div></div><div id="aioOwnerEconomy"></div>';
renderOfflineQueuePanel(root);
root.querySelectorAll('[data-claim]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await rpc('aio_claim_quest',{p_quest_id:b.dataset.claim});toast('Quest reward claimed!');renderEconomy()}catch(e){toast(e.message||'Could not claim reward.');b.disabled=false}});root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyGame(b.dataset.buy));renderBalance();renderOwnerTools()
}catch(e){const cache=readOfflineEconomyCache();if(cache?.userId===currentUser.id){renderCachedOfflineEconomy(root,cache);const notice=root.querySelector('.aio-offline-notice');if(notice)notice.textContent='Showing saved A-Coins data because the live shop could not be reached. Purchases remain pending until the server confirms them.';return}root.innerHTML='<div class="aio-economy-empty"><h3>Could not load A-Coins</h3><p>'+esc(e.message||'Request failed')+'</p><button class="aio-secondary-button" id="aioEconomyRetry">Retry</button></div>';$('aioEconomyRetry').onclick=renderEconomy}}
async function buyGame(id){try{if(!signed())throw Error('Sign in before purchasing.');if(!navigator.onLine){queueOfflineGame(id);renderCachedOfflineEconomy($('aioEconomyContent'),readOfflineEconomyCache());return;}if(!confirm('Buy '+gameName(id)+' with A-Coins?'))return;const r=await rpc('aio_buy_game',{p_game_id:id});toast(r.alreadyOwned?'Already owned.':'Purchase complete.');priceCache.delete(id);renderEconomy()}catch(e){toast(e.message||'Purchase failed.')}}
async function renderOwnerTools(){const host=$('aioOwnerEconomy');if(!host)return;try{const d=await rpc('aio_owner_economy_admin');const options=[];try{GAMES.forEach(g=>options.push({id:slug(g.id||g.name),name:g.name}))}catch{}host.innerHTML='<div class="aio-owner-economy"><div class="aio-quest-heading"><h3>Owner pricing</h3><span>Owner permission verified by Supabase.</span></div><div class="aio-owner-price-form"><label>Game<select id="aioPriceGame">'+options.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join('')+'</select></label><label>Price in A-Coins<input id="aioPriceAmount" type="number" min="0" max="100000" value="0"></label><button class="aio-primary-button" id="aioSavePrice">Save price</button></div><p class="aio-onboard-note">Set price to 0 to make a game free.</p><h4>Purchase history</h4><div class="aio-purchase-history">'+(d.purchases||[]).slice(0,30).map(p=>'<div class="aio-pricing-row"><span>'+esc(gameName(p.gameId))+' · '+esc(String(p.userId).slice(0,8))+'</span><strong>'+Number(p.price).toLocaleString()+' ◈</strong>'+(p.refundedAt?'<span>Refunded</span>':'<button class="aio-small-primary" data-refund="'+esc(p.id)+'">Refund</button>')+'</div>').join('')+'</div></div>';$('aioSavePrice').onclick=async()=>{const p=Number($('aioPriceAmount').value);if(!Number.isInteger(p)||p<0||p>100000)return toast('Use a whole number from 0 to 100,000.');try{await rpc('aio_set_game_price',{p_game_id:$('aioPriceGame').value,p_price:p});priceCache.clear();toast('Price saved.');renderEconomy()}catch(e){toast(e.message||'Price change failed.')}};host.querySelectorAll('[data-refund]').forEach(b=>b.onclick=async()=>{if(!confirm('Refund this purchase?'))return;try{await rpc('aio_refund_game_purchase',{p_purchase_id:b.dataset.refund});toast('Refund completed.');renderEconomy()}catch(e){toast(e.message||'Refund failed.')}});await renderSubmissionAdmin(host)}catch(e){host.innerHTML='';if(!/Owner permission required/i.test(e.message||''))console.info(e.message)}}

function addSubmissionPanel(){const grid=$('gameGrid');if(!grid||$('aioSubmitGamePanel'))return;const panel=document.createElement('details');panel.id='aioSubmitGamePanel';panel.className='aio-submit-panel';panel.innerHTML='<summary>Submit a community game</summary><p>Submissions stay private until an owner approves them. Use HTTPS links; submitted code is sandboxed away from the main app.</p><form id="aioSubmitGameForm"><div class="aio-submit-grid"><label>Game title<input name="title" required minlength="3" maxlength="80" placeholder="Game title"></label><label>Category<select name="category"><option>Arcade</option><option>Classic</option><option>Puzzle</option><option>Action</option><option>Platformer</option><option>Racing</option><option>Sports</option><option>Casual</option><option>Idle</option><option>Other</option></select></label><label class="wide">Game URL (HTTPS)<input name="game_url" type="url" required placeholder="https://example.com/game"></label><label class="wide">Description<textarea name="description" maxlength="1000" rows="2" placeholder="What is the game about?"></textarea></label><label>Thumbnail URL (optional)<input name="thumbnail_url" type="url" placeholder="https://..."></label><label>Creator name<input name="creator_name" maxlength="80" placeholder="Creator / studio"></label><label class="wide">Controls<input name="controls" maxlength="500" placeholder="Instructions from the original game"></label></div><button class="aio-primary-button" type="submit">Submit for review</button> <span id="aioSubmitStatus" role="status"></span></form></details>';const toolbar=$('aioDiscoveryFilters');grid.parentElement.insertBefore(panel,toolbar||grid);$('aioSubmitGameForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,status=$('aioSubmitStatus');if(!signed()){toast('Sign in before submitting a game.');window.handleAccountClick?.();return}const data=Object.fromEntries(new FormData(form).entries());if(!/^https:\/\/\S+$/i.test(data.game_url)||data.thumbnail_url&&!/^https:\/\/\S+$/i.test(data.thumbnail_url)){status.textContent='Use HTTPS links for the game and thumbnail.';return}const btn=form.querySelector('button[type="submit"]');btn.disabled=true;status.textContent='Sending for moderation…';try{await rpc('aio_submit_game',{p_title:data.title,p_description:data.description||'',p_category:data.category,p_thumbnail_url:data.thumbnail_url||'',p_game_url:data.game_url,p_controls:data.controls||'',p_creator_name:data.creator_name||''});form.reset();status.textContent='Submitted. It will appear after owner approval.';toast('Community game submitted for review.')}catch(err){status.textContent=err.message||'Submission failed.'}finally{btn.disabled=false}})}
async function loadCommunityGames(){try{if(typeof supabaseClient==='undefined'||!supabaseClient||typeof GAMES==='undefined')return;const r=await supabaseClient.from('aio_game_submissions').select('id,title,description,category,thumbnail_url,game_url,controls,creator_name,featured,coin_price').eq('status','approved').order('featured',{ascending:false}).order('created_at',{ascending:false}).limit(100);if(r.error)throw r.error;let changed=false;for(const row of r.data||[]){if(!/^https:\/\/\S+$/i.test(row.game_url||'')||GAMES.some(g=>g.id==='community-'+row.id))continue;GAMES.push({id:'community-'+row.id,name:row.title,description:row.description||'',cat:row.category||'Other',url:row.game_url,source:'Community',sourceUrl:row.game_url,img:row.thumbnail_url||'',tag:row.featured?'Featured community':'Community',controls:row.controls||'See original game instructions.',license:'Community submission; rights not independently verified',coinPrice:Number(row.coin_price||0),coinReward:0,questEligible:false,featured:!!row.featured,new:true,difficulty:'Normal',fullscreenSupported:true,multiplayer:false,creatorName:row.creator_name||''});changed=true}if(changed){if(typeof renderFilters==='function')renderFilters();if(typeof renderGames==='function')renderGames();addSourceLabels()}}catch(e){console.info('Community game feed unavailable:',e.message||e)}}
async function renderSubmissionAdmin(host){try{const rows=await rpc('aio_owner_game_submissions');const section=document.createElement('section');section.className='aio-community-moderation';section.innerHTML='<div class="aio-quest-heading"><h3>Community game moderation</h3><span>Owner access checked by Supabase.</span></div>';const pending=(rows||[]).filter(x=>x.status==='pending'||x.status==='approved');if(!pending.length){const p=document.createElement('p');p.className='aio-onboard-note';p.textContent='No pending or approved submissions.';section.append(p)}pending.forEach(item=>{const card=document.createElement('article');card.className='aio-moderation-card';card.innerHTML='<div class="aio-moderation-info"><strong>'+esc(item.title)+'</strong><span>'+esc(item.category)+' · '+esc(item.creatorName||'Creator not supplied')+' · '+esc(item.status)+'</span><p>'+esc(item.description||'No description')+'</p><a href="'+esc(item.gameUrl)+'" target="_blank" rel="noopener noreferrer">Review original game</a></div><label>Price<input class="aio-moderation-price" type="number" min="0" max="100000" step="1" value="'+Number(item.coinPrice||0)+'"></label><label class="aio-feature-toggle"><input type="checkbox" '+(item.featured?'checked':'')+'> Feature</label><div class="aio-moderation-actions">'+(item.status==='pending'?'<button type="button" class="aio-small-primary" data-review="approved">Approve</button><button type="button" class="aio-secondary-button" data-review="rejected">Reject</button>':'<button type="button" class="aio-small-primary" data-review="approved">Save settings</button><button type="button" class="aio-secondary-button" data-review="removed">Remove</button>')+'</div>';card.querySelectorAll('[data-review]').forEach(btn=>btn.onclick=async()=>{const price=Number(card.querySelector('.aio-moderation-price').value),featured=card.querySelector('.aio-feature-toggle input').checked;if(!Number.isInteger(price)||price<0||price>100000){toast('Enter a valid price.');return}btn.disabled=true;try{await rpc('aio_review_game_submission',{p_submission_id:item.id,p_status:btn.dataset.review,p_featured:featured,p_coin_price:price,p_review_note:''});toast(btn.dataset.review==='approved'?'Game approved.':'Submission rejected.');await loadCommunityGames();await renderEconomy()}catch(e){toast(e.message||'Moderation failed.');btn.disabled=false}});section.append(card)});const old=host.querySelector('.aio-community-moderation');if(old)old.replaceWith(section);else host.append(section)}catch(e){if(!/Owner permission required/i.test(e.message||''))console.info('Community moderation panel unavailable:',e.message||e)}}

async function renderBalance(){if(!signed())return;try{const s=await rpc('aio_get_economy_state');if($('aioCoinBalance'))$('aioCoinBalance').textContent=Number(s.balance||0).toLocaleString()+' A-Coins'}catch{}}
function ensureContext(){if($('aioContextMenu'))return;const m=document.createElement('div');m.id='aioContextMenu';m.className='aio-context-menu';m.setAttribute('role','menu');document.body.append(m);document.addEventListener('contextmenu',e=>{if(!matchMedia('(pointer:fine)').matches||e.defaultPrevented)return;const t=e.target;if(t.closest('input,textarea,select,[contenteditable="true"],.game-stage,#aioOnboarding,#aioCoinModal')||String(getSelection()||'').trim())return;e.preventDefault();openContext(e.clientX,e.clientY)});let touchTimer=null,touchOrigin=null;const cancelTouchMenu=()=>{if(touchTimer!==null)clearTimeout(touchTimer);touchTimer=null;touchOrigin=null};document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!e.isPrimary||e.target.closest('input,textarea,select,[contenteditable="true"],button,a,[role="button"],.game-stage,#aioOnboarding,#aioCoinModal'))return;touchOrigin={x:e.clientX,y:e.clientY};touchTimer=setTimeout(()=>{if(touchOrigin){const p=touchOrigin;touchOrigin=null;touchTimer=null;openContext(p.x,p.y)}},650)},{passive:true});document.addEventListener('pointerup',cancelTouchMenu,{passive:true});document.addEventListener('pointercancel',cancelTouchMenu,{passive:true});document.addEventListener('pointermove',e=>{if(touchOrigin&&Math.hypot(e.clientX-touchOrigin.x,e.clientY-touchOrigin.y)>12)cancelTouchMenu()},{passive:true});document.addEventListener('pointerdown',e=>{if(!e.target.closest('#aioContextMenu'))m.classList.remove('open')});window.addEventListener('resize',()=>m.classList.remove('open'));document.addEventListener('keydown',e=>{if((e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10'))&&!e.target.closest('input,textarea,select,[contenteditable="true"]')){e.preventDefault();const rect=e.target.getBoundingClientRect?.();openContext(rect?rect.left:12,rect?rect.bottom:12)}if(e.key==='Escape'){m.classList.remove('open');if($('gameModal')?.classList.contains('open'))$('aioGameToolbar')?.classList.toggle('expanded')}if(e.altKey&&e.shiftKey&&e.key.toLowerCase()==='p'&&$('gameModal')?.classList.contains('open')){e.preventDefault();freeze(!frozen)}if(frozen&&e.key==='Tab'&&$('aioFrozenOverlay')?.contains(document.activeElement)){e.preventDefault();$('aioResumeBtn')?.focus()}if(frozen&&!m.classList.contains('open')&&!$('aioFrozenOverlay')?.contains(e.target)&&!['Tab','Escape','Shift','Enter',' '].includes(e.key)&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();e.stopPropagation()}if(m.classList.contains('open')){const bs=[...m.querySelectorAll('button')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();menuIndex=(menuIndex+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length;bs[menuIndex]?.focus()}else if(e.key==='Home'){e.preventDefault();menuIndex=0;bs[0]?.focus()}else if(e.key==='End'){e.preventDefault();menuIndex=bs.length-1;bs[menuIndex]?.focus()}}})}
function openContext(x,y){const m=$('aioContextMenu'),items=[['Back','Go back',()=>history.back()],['Forward','Go forward',()=>history.forward()],['Reload','Reload page',()=>location.reload()],['Games','Browse games',()=>document.querySelector('[data-scroll="games"]')?.click()],['Random game','Launch a random game',()=>{if(GAMES?.length)window.openGame(Math.floor(Math.random()*GAMES.length))}],['A-Coins & Quests','View progression',openEconomy],['Settings','Personalisation',()=>window.openSettings?.()],['Toggle wallpaper','Show or hide wallpaper',()=>document.documentElement.classList.toggle('aio-wallpaper-hidden')],['Toggle theme','Switch theme',()=>document.querySelector('#darkBtn')?.click()]];if($('gameModal')?.classList.contains('open'))items.splice(5,0,['Freeze / Resume','Alt + Shift + P',()=>freeze(!frozen)],['Fullscreen','Toggle game fullscreen',()=>window.fullscreenGame?.()]);m.innerHTML=items.map((it,i)=>'<button role="menuitem" data-i="'+i+'"><span>'+it[0]+'</span><small>'+it[1]+'</small></button>').join('');m.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{m.classList.remove('open');try{const result=items[i][2]();if(result&&typeof result.then==='function')result.catch(e=>toast('Menu action failed: '+(e?.message||'try again')))}catch(e){toast('Menu action failed: '+(e?.message||'try again'))}});m.classList.add('open');m.style.left=Math.max(8,Math.min(x,innerWidth-228))+'px';m.style.top=Math.max(8,Math.min(y,innerHeight-Math.min(items.length*45+10,innerHeight-16)-8))+'px';menuIndex=0;m.querySelector('button')?.focus()}
function init(){addSlime();addOpenSourceGames();patchDiscoveryFilter();enhanceSmartAI();ensureOnboard();addDiscoveryToolbar();ensureCoinUI();startAioLiveClock();ensureContext();setupGameControls();patchGameLaunch();addSubmissionPanel();loadCommunityGames();addSourceLabels();loadPrices();const grid=$('gameGrid');if(grid)new MutationObserver(()=>{addSourceLabels()}).observe(grid,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest('#settingsBtn'))setTimeout(addTutorialSetting,100)});new MutationObserver(addTutorialSetting).observe(document.body,{childList:true,subtree:true});if(!localStorage.getItem(KEY))setTimeout(()=>{if(!document.hidden)openOnboard(false)},800);renderBalance();const account=$('accountLabel');if(account)new MutationObserver(()=>{renderBalance();patchGameLaunch();loadPrices();loadCommunityGames();syncOfflineGamePurchases()}).observe(account,{childList:true,subtree:true,characterData:true});document.addEventListener('visibilitychange',()=>{});window.addEventListener('online',()=>{syncOfflineGamePurchases()});window.addEventListener('load',()=>{patchGameLaunch();renderBalance();loadPrices();loadCommunityGames();addSubmissionPanel();syncOfflineGamePurchases()})}
window.openAioEconomy=openEconomy;window.openAioOnboarding=()=>openOnboard(true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();